package com.mentalmadad.controller;
import com.mentalmadad.dto.response.*; import com.mentalmadad.service.DoctorService; import org.springframework.data.domain.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/doctors") public class DoctorController { private final DoctorService service; public DoctorController(DoctorService s){service=s;} @GetMapping public Page<DoctorResponse> list(@RequestParam(required=false) String specialization,@RequestParam(required=false) String name,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="12") int size){return service.list(specialization,name,page,size);} @GetMapping("/search") public Page<DoctorResponse> search(@RequestParam(required=false) String specialization,@RequestParam(required=false) String name,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="12") int size){return service.list(specialization,name,page,size);} @GetMapping("/{id}") public DoctorDetailResponse get(@PathVariable Long id){return service.get(id);} }
